# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student


def _verify(students: List[Student]) -> None:
    if not students:
        raise ValueError("no students for contact sheet")
    for stud in students:
        if not (stud.email or "").strip():
            msg = f"no email for {stud.display_name}"
            raise ValueError(msg)


def _sort_key(stud: Student) -> Tuple[str, str, str]:
    last = stud.last_name.lower()
    return (last, stud.first_name.lower(), stud.student_id)


def _widths(students: List[Student]) -> Tuple[int, int]:
    return (
        max(len(stud.display_name) for stud in students),
        max(len(stud.section) for stud in students),
    )


def _row(stud: Student, namewide: int, sectwide: int) -> str:
    name = f"{stud.display_name:<{namewide}}"
    return f"{name}  {stud.section:<{sectwide}}  {stud.email}"


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    members = list(students)
    _verify(members)
    ordered = sorted(members, key=_sort_key)
    namewide, sectwide = _widths(ordered)
    return [_row(stud, namewide, sectwide) for stud in ordered]

