# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def _make(last, first, section, email="a@x.org"):
    return Student("id" + last, last, first, section, email)


PEOPLE = [
    _make("Thistle", "Bram", "A", "b@x.org"),
    _make("Quill", "Ann", "10", "q@x.org"),
]
EXPECTED = [
    "Quill, Ann     10  q@x.org",
    "Thistle, Bram  A   b@x.org",
]


class ContactRowTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows(PEOPLE)
        self.assertEqual(rows, EXPECTED)

    def test_missing_email_names_student(self):
        people = [_make("Quill", "Ann", "A", None)]
        with self.assertRaises(ValueError) as caught:
            contact_rows(people)
        self.assertIn("Quill, Ann", str(caught.exception))

    def test_blank_email_is_missing(self):
        people = [_make("Quill", "Ann", "A", "  ")]
        with self.assertRaises(ValueError):
            contact_rows(people)

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            contact_rows([])
